using System; using System.Collections.Generic;
namespace SuijinMaterials.Merchants { public sealed class MerchantListingSettings { public MerchantListingSettings(bool enabled,int price,int stack){Enabled=enabled;Price=price;Stack=stack;} public bool Enabled{get;} public int Price{get;} public int Stack{get;} } public sealed class MerchantStockSettings { private readonly IReadOnlyDictionary<string,MerchantListingSettings> values; public MerchantStockSettings(IDictionary<string,MerchantListingSettings> values){this.values=new Dictionary<string,MerchantListingSettings>(values??throw new ArgumentNullException(nameof(values)),StringComparer.Ordinal);} public MerchantListingSettings Get(string id)=>values[id]; } }
